/**
 * @file Player.h
 * @brief Player - Commodore 64 music player (.sid files) for the ESP32.
 *
 * The library connects the C64/SID emulation (SidEngine) with the I2S audio output
 * and the file sources (SidSource.h): flash memory (LittleFS), SD card...
 * Each source has its own current folder. Sound is generated by a separate
 * FreeRTOS task started in begin(). Call the file and playback methods from one
 * task (e.g. loop()); volume, pause and status are safe from any task.
 *
 * Methods returning String return an empty string on success,
 * and an error description on failure.
 *
 * @code
 *   Player player;
 *   player.begin();               // I2S + file sources + audio task
 *   player.setSource(SourceType::SdCard);
 *   player.cd("Hubbard");         // folder of the current source, ".." = one level up
 *   player.play("Commando.sid");  // or playIndex(1), or a full path "/Hubbard/Commando.sid"
 *   player.pause(); player.resume(); player.stop();
 *   player.setVolume(70); player.setMute(true);
 * @endcode
 */
#pragma once
#include <Arduino.h>
#include <FS.h>
#include <vector>
#include "sidplayer.h"
#include "SidSource.h"

/**
 * @brief Hardware and task configuration passed to Player::begin().
 */
struct PlayerConfig {
    uint32_t sampleRate = 44100;  ///< Output sample rate in Hz.
    int pinBck = 26;              ///< External I2S DAC (PCM5102A, MAX98357A...): BCK pin.
    int pinWs = 25;               ///< I2S WS (LRCK) pin.
    int pinData = 22;             ///< I2S data out pin.
    uint8_t volume = 80;          ///< Initial volume 0..100.
    int audioCore = 1;            ///< CPU core for the audio task.
    int audioPriority = 5;        ///< FreeRTOS priority of the audio task.
    bool formatFsIfFailed = true; ///< Format LittleFS when it cannot be mounted.
    int sdCs = 5, sdSck = 18, sdMiso = 19, sdMosi = 23;   ///< SD card SPI pins (used when -DPLAYER_SOURCE_SD=1).
    uint32_t sdFreq = 20000000;   ///< SD card SPI clock in Hz.
};
// The built-in DAC of the classic ESP32 (GPIO25/26) is enabled with the -DSID_OUTPUT_INTERNAL_DAC flag.

/** @brief Playback state. */
enum class PlayerState : uint8_t { Stopped, Playing, Paused };

/// Entry of the current folder listing: folders first, then files, alphabetically.
typedef SourceEntry PlayerFile;

/**
 * @brief Snapshot of the player state returned by Player::status().
 */
struct PlayerStatus {
    PlayerState state;            ///< Playback state.
    bool loaded;                  ///< Whether any file is loaded.
    String file;                  ///< Full path of the current file, e.g. "/Hubbard/Commando.sid".
    SourceType fileSource;        ///< Source of the current file.
    SourceType source;            ///< Active source (listing, next/prev, upload).
    String dir;                   ///< Current folder of the active source.
    String title, author, released;   ///< Tune information from the file header.
    int song, songs;              ///< Current subtune / number of subtunes.
    uint32_t ms;                  ///< Playback time of the subtune in ms.
    bool rsid, ntsc;              ///< RSID file / NTSC timing.
    int sidModel;                 ///< Model from the file: 0 = 6581, 1 = 8580.
    float frameHz;                ///< Rate of the play routine calls in Hz.
    uint8_t volume;               ///< Volume 0..100.
    bool muted;                   ///< Mute on.
    int modelSetting;             ///< -1 auto, 0 = 6581, 1 = 8580.
    bool testTone;                ///< 440 Hz test tone on.
    unsigned cpuLoad;             ///< Audio task load in %.
    const char* engine;           ///< Name of the SID emulation engine.
};

/**
 * @brief .sid player: file sources, folder navigation, playback control and the I2S audio task.
 */
class Player {
public:
    /** @brief Creates a stopped player; every source starts in the "/" folder. */
    Player();

    /**
     * @brief Starts the file sources, the I2S output and the audio task.
     * @param cfg Configuration (copied).
     * @return true if flash (LittleFS) and I2S work; a missing SD card is not an error.
     */
    bool begin(const PlayerConfig& cfg = PlayerConfig());
    /** @brief Whether I2S was set up. @return true if audio works. */
    bool audioOk() const { return i2sError_ == 0; }
    /** @brief I2S setup result. @return esp_err_t name, or "OK". */
    const char* audioError() const;
    /** @brief Configuration passed to begin(). @return Reference to the configuration. */
    const PlayerConfig& config() const { return cfg_; }

    // --- file sources ---
    /** @brief Active source. @return Source type. */
    SourceType source() const { return source_; }
    /**
     * @brief Switches the active source.
     * @param type New source.
     * @return "" on success; an error when the source is not compiled in or not ready
     *         (the source is still switched when it is only not ready).
     */
    String setSource(SourceType type);
    /** @brief Description of the active source. @return Reference into PLAYER_SOURCES. */
    const SourceInfo& sourceInfo() const;
    /** @brief Object of the active source. @return Reference to the source. */
    SidSource& activeSource() { return *sources_[uint8_t(source_)]; }
    /** @brief Whether the active source can be read (e.g. SD card inserted). @return true if ready. */
    bool sourceReady();
    /** @brief Error of the active source. @return Error text, "" when none. */
    String sourceError();

    // --- folders (each source remembers its own) ---
    /** @brief Current folder of the active source. @return Folder path. */
    String dir() const { return dir_[uint8_t(source_)]; }
    /**
     * @brief Current folder of a given source.
     * @param type Source.
     * @return Folder path.
     */
    String dir(SourceType type) const { return dir_[uint8_t(type)]; }
    /**
     * @brief Changes the current folder of the active source.
     * @param dir "x" (relative), "/a/b" (absolute), ".." (parent) or "/" (root).
     * @return "" on success, otherwise an error description.
     */
    String cd(const String& dir);
    /**
     * @brief Sets the folder of a source without checking that it exists (for restoring settings).
     * @param type Source.
     * @param dir  Folder path ("/" is used when invalid).
     */
    void setDir(SourceType type, const String& dir);

    // --- files in the current folder ---
    /**
     * @brief Listing of the current folder (cached until refreshFiles() or a change).
     *
     * If the folder cannot be read, the source falls back to the root folder.
     * @return Folders followed by .sid files, each group sorted alphabetically.
     */
    const std::vector<PlayerFile>& files();
    /** @brief Re-reads the folder on the next files() call. */
    void refreshFiles();
    /** @brief Whether the listing hit MAX_LIST. @return true if entries may be missing. */
    bool filesTruncated() const { return truncated_; }
    /** @brief Number of files in the current folder. @return Files only, without folders. */
    int fileCount();
    /**
     * @brief Name of the n-th file in the current folder.
     * @param index File number from 1 (files only).
     * @return File name, "" when out of range.
     */
    String fileName(int index);
    /**
     * @brief Position of a file in the current folder.
     * @param nameOrPath File name or full path.
     * @return File number from 1, 0 = not in the current folder.
     */
    int fileIndex(const String& nameOrPath);
    /**
     * @brief Converts a name to a full path in the current folder.
     * @param nameOrPath Name, or a path starting with "/" (returned unchanged).
     * @return Full path.
     */
    String path(const String& nameOrPath) const;
    /**
     * @brief Deletes a .sid file (stops playback if it is the current file).
     * @param nameOrPath File name or full path.
     * @return true if deleted.
     */
    bool removeFile(const String& nameOrPath);
    /** @brief Free space of the active source. @return Bytes. */
    uint64_t freeSpace();
    /** @brief Capacity of the active source. @return Bytes. */
    uint64_t totalSpace();
    /** @brief Whether uploading to the active source is allowed and possible. @return true if allowed. */
    bool uploadAllowed();
    /** @brief Whether the active source allows deleting files. @return true if allowed. */
    bool deleteAllowed();
    /**
     * @brief Prepares an upload: builds the path of the uploaded file in the current folder.
     *
     * Stops playback when the file being replaced is playing.
     * @param fileName Original file name (sanitized).
     * @param path     Receives the full target path ("" on error).
     * @return "" on success, otherwise an error description.
     */
    String prepareUpload(const String& fileName, String& path);
    /**
     * @brief Opens a file of the active source for writing and invalidates the listing.
     * @param path Full path (from prepareUpload()).
     * @return Open file (invalid on failure).
     */
    fs::File openWrite(const String& path);
    /**
     * @brief Deletes any path in the active source (stops playback if it is the current file).
     * @param path Full path.
     * @return true if deleted.
     */
    bool removePath(const String& path);
    /**
     * @brief Turns any name into a safe .sid file name.
     *
     * Keeps letters, digits, ".", "-", "_"; spaces become "_"; at most 60 characters.
     * @param name Name or path.
     * @return Clean name, "" = not allowed.
     */
    static String sanitizeName(const String& name);
    static const size_t MAX_FILE_SIZE = 0x10000 + 0x7C + 2;   ///< Largest accepted .sid file (64 KB + header + load address).
    static const size_t MAX_LIST = 1000;          ///< Maximum number of entries in one folder.

    // --- playback ---
    /**
     * @brief Loads and plays a file from the active source.
     * @param nameOrPath File name in the current folder or a full path.
     * @param song       Subtune (1-based); 0 = default from the file.
     * @return "" on success, otherwise an error description.
     */
    String play(const String& nameOrPath, int song = 0);
    /**
     * @brief Plays the n-th file of the current folder.
     * @param index File number from 1 (files only).
     * @param song  Subtune; 0 = default from the file.
     * @return "" on success, otherwise an error description.
     */
    String playIndex(int index, int song = 0);
    /** @brief Plays the next file (only in the current folder, wraps around). @return "" or an error. */
    String nextFile();
    /** @brief Plays the previous file (only in the current folder, wraps around). @return "" or an error. */
    String prevFile();
    /** @brief Stops playback. */
    void stop();
    /** @brief Pauses playback (the emulation stops). */
    void pause();
    /** @brief Resumes after pause(); after stop() restarts the current subtune. */
    void resume();
    /** @brief Pauses when playing, otherwise resumes. */
    void togglePause();
    /**
     * @brief Starts a subtune of the loaded file (wraps around at both ends).
     * @param song Subtune number (1-based); < 1 = last, > count = first.
     * @return "" on success, error when no file is loaded.
     */
    String setSong(int song);
    /** @brief Starts the next subtune. @return "" or an error. */
    String nextSong();
    /** @brief Starts the previous subtune. @return "" or an error. */
    String prevSong();
    /** @brief Restarts the current subtune from the beginning. @return "" or an error. */
    String restartSong();

    // --- sound ---
    /**
     * @brief Sets the volume.
     * @param percent Volume 0..100 (clamped).
     */
    void setVolume(int percent);
    /** @brief Current volume. @return 0..100. */
    int volume() const { return volume_; }
    /**
     * @brief Increases the volume.
     * @param step Step in percent.
     */
    void volumeUp(int step = 10) { setVolume(volume_ + step); }
    /**
     * @brief Decreases the volume.
     * @param step Step in percent.
     */
    void volumeDown(int step = 10) { setVolume(volume_ - step); }
    /**
     * @brief Mutes or unmutes (the music keeps playing silently).
     * @param on true = mute.
     */
    void setMute(bool on) { muted_ = on; }
    /** @brief Toggles mute. */
    void toggleMute() { muted_ = !muted_; }
    /** @brief Mute state. @return true if muted. */
    bool muted() const { return muted_; }
    /**
     * @brief Sets the SID model and restarts the subtune if one is playing or paused.
     * @param model -1 auto, 0 = 6581, 1 = 8580 (clamped).
     * @return "" on success, otherwise an error description.
     */
    String setModel(int model);
    /** @brief SID model setting. @return -1 auto, 0 = 6581, 1 = 8580. */
    int model() const { return modelSetting_; }
    /**
     * @brief Enables a 440 Hz sine instead of the music (to test the amplifier).
     * @param on true = test tone.
     */
    void setTestTone(bool on) { testTone_ = on; }
    /** @brief Test tone state. @return true if on. */
    bool testTone() const { return testTone_; }

    // --- state ---
    /** @brief Collects the current state. @return Status snapshot. */
    PlayerStatus status();
    /** @brief Playback state. @return State. */
    PlayerState state() const { return state_; }
    /** @brief Whether music is playing. @return true when state is Playing. */
    bool isPlaying() const { return state_ == PlayerState::Playing; }
    /** @brief Audio task load. @return Render time of a block as % of its duration (>100% = ESP32 cannot keep up). */
    unsigned cpuLoad() const;

private:
    /**
     * @brief FreeRTOS entry point of the audio task.
     * @param arg Pointer to the Player.
     */
    static void audioTaskEntry(void* arg);
    /** @brief Audio task loop: renders blocks (music, test tone or silence) and writes them to I2S. */
    void audioTask();
    /** @brief Installs the I2S driver (external DAC or built-in DAC). @return true on success. */
    bool setupI2S();
    /**
     * @brief Reads a file from the active source, loads it into the emulator and starts it.
     * @param path Full path.
     * @param song Subtune; 0 = default.
     * @return "" on success, otherwise an error description.
     */
    String loadAndStart(const String& path, int song);
    /**
     * @brief Plays the next / previous file in the current folder (folders are skipped).
     * @param delta +1 next, -1 previous.
     * @return "" on success, otherwise an error description.
     */
    String stepFile(int delta);
    /** @brief Number of folders at the start of the listing. @return Folder count. */
    int dirCount();
    /** @brief Takes the mutex protecting the emulator. */
    void lock();
    /** @brief Releases the mutex. */
    void unlock();

    PlayerConfig cfg_;             ///< Configuration from begin().
    SidPlayer sid_;                ///< C64/SID emulator.
    void* mutex_;                  ///< FreeRTOS mutex (SemaphoreHandle_t) protecting sid_.
    volatile PlayerState state_;   ///< Playback state.
    volatile bool muted_;          ///< Mute on.
    volatile bool testTone_;       ///< Test tone on.
    volatile int volume_;          ///< Volume 0..100.
    volatile uint32_t renderUs_;   ///< Render time of the last audio block in microseconds.
    int modelSetting_;             ///< -1 auto, 0 = 6581, 1 = 8580.
    int i2sError_;                 ///< I2S setup result (esp_err_t, 0 = OK).
    String file_;                  ///< Full path of the current file.
    SourceType fileSource_;        ///< Source of the current file.
    SidSource* sources_[SOURCE_TYPE_COUNT];   ///< Source objects (nullptr = not compiled in).
    SourceType source_;            ///< Active source.
    String dir_[SOURCE_TYPE_COUNT];   ///< Current folder of each source.
    std::vector<PlayerFile> list_; ///< Cached listing of the current folder.
    bool listValid_;               ///< list_ is up to date.
    bool truncated_;               ///< list_ hit MAX_LIST.
};
